// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(address actor, uint256 w, uint256 r) public {
        vm.assume(actor != address(c) && actor != address(0));
        vm.warp(w);
        vm.roll(r);
        uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        vm.assume(random == 1);
        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();
        // Rule: when random == 1 the reference performs no payout and no reset, so the pot
        // must be nonzero after the play. The mutant (trigger on random == 1) resets pot to 0.
        assertTrue(c.pot() != 0);
    }
}
